#include "exotic/autonomy/agents/in_memory_repository.hpp"
#include "exotic/autonomy/agents/registry.hpp"
#include <cassert>
int main(){using namespace exotic::autonomy::agents;InMemoryAgentRepository repo;AgentRegistry registry{repo};CapabilityDefinition parent;parent.key="software";parent.name="Software";registry.define_capability(parent);CapabilityDefinition child;child.key="software.cpp";child.parent_key="software";child.name="C++";registry.define_capability(child);AgentIdentity agent;agent.identity_key="builder-1";agent.display_name="Builder";agent.workload.maximum_tasks=2;const auto id=registry.register_agent(agent);assert(registry.activate(id));registry.grant_capability({id,"software.cpp",0.9,0.8,0,0,exotic::autonomy::Clock::now()});ToolPermission permission;permission.agent_id=id;permission.tool_key="compiler";permission.operations={"build","test"};registry.grant_tool_permission(permission);assert(registry.tool_allowed(id,{"compiler","build","*",true}));assert(!registry.tool_allowed(id,{"shell","execute","*",true}));auto loaded=repo.load_agent(id);assert(loaded&&loaded->status==AgentStatus::Active);assert(repo.load_agent_capabilities(id).size()==1);return 0;}
